"""Replay double of `methods.Learner`: a DQN learner over 10 snake transitions (the
`core.World` double's episode, twice).

`act` serves the recorded exploring actions for the recorded observations (`LookupError` for
others); `observe` keeps each transition in `observed` (`recorded` holds the 10 it was trained
on); `policy()` is a frozen replay policy of greedy actions; `state_dict()` the recorded state.
"""

import copy

import numpy as np

from rllab.core import Array
from rllab.methods import Transition


class ReplayLearner:
    def __init__(self, fx, rec) -> None:
        replay_policy = fx.module("core.Policy").ReplayPolicy
        self._exploring = replay_policy(fx, rec["acts"])
        self._frozen = replay_policy(fx, rec["policy"]["calls"])
        self.recorded = [fx.decode(Transition, t) for t in rec["transitions"]]
        self.observed: list[Transition] = []
        self._state = rec["state_dict"]

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        return self._exploring.act(obs, rng)

    def observe(self, t: Transition) -> None:
        self.observed.append(t)

    def policy(self):
        return self._frozen

    def state_dict(self) -> dict[str, object]:
        return copy.deepcopy(self._state)


def build(fx, case: str) -> ReplayLearner:
    return ReplayLearner(fx, fx.recording(case))
